class stringx { int value; };
class Font;
struct color32 { unsigned int value; };
struct vector3d { float x, y, z; };
typedef float nglVector[4];
struct nglFileBuf { void *Buf; int Size; };

class StringList
{
public:
    stringx data;
    float x;
    float y;
    float fall_speed[150];
    float drift_speed[150];
    int drift_max[150];
    float delta_x[150];
    float delta_y[150];
};

class TextString
{
protected:
    Font *font;
    stringx text;
    float x;
    float y;
    int z;
    int hJustify;
    int vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;
public:
    bool checkTime;
    float time;
    bool no_color;
    color32 color;

    virtual ~TextString();
    virtual void Update(float);
    virtual void Draw();
    virtual void setHJustify(int);
    virtual void setVJustify(int);
    virtual void setFont(Font *);
    virtual void setButtonScale(float);
    virtual void numberSpacing(bool);
    virtual void changeText(stringx);
    virtual void changeScale(float);
    virtual void changePos(float, float);
    virtual void changeX(float);
    virtual void changeY(float);
    virtual void changeZ(int);
    virtual void ChangeFade(bool, bool, float);
    virtual void SetFade(float);
    virtual float getX();
    virtual float getY();
    virtual int getZ();
    virtual stringx getText();
    virtual float GetScale() const;
    virtual float GetButtonScale() const;
    virtual bool GetNumberSpacing() const;
    virtual Font *GetFont();
    virtual int GetHJustify() const;
    virtual int GetVJustify() const;
    virtual void setLineSpacing(int);
    virtual void resetLineSpacing();
    virtual void UpdateInScene(bool);
    virtual void SetLocation3D(vector3d);
    virtual vector3d GetLocation3D();
    virtual void SetBehaviorNF(float, float);
    virtual void SetBehavior(bool);
protected:
    virtual void Render();
    virtual void Render(stringx *, float, float);
    virtual void Render(stringx *, float, float, float *, float *, bool);
};

class BoxText : public TextString
{
protected:
    int width;
    int height;
    bool reverse;
    int max_box_strings;
    StringList *box_strings;
    int box_str_count;
    nglFileBuf fileBuf;
    bool non_floating_behavior;
    nglVector location_2d;
    nglVector location_3d;
    float real_scale;
    float real_x;
    float real_y;
    float adjusted_x;
    float adjusted_y;
    bool scrollable;
    int max_vis_lines;
    int first_vis;
public:
    virtual void Draw();
};

void BoxText::Draw()
{
    if(!checkTime || time > 0)
    {
        int start = 0;
        int end = box_str_count;
        if(scrollable)
        {
            start = first_vis;
            end = first_vis + max_vis_lines;
            if(end > box_str_count) end = box_str_count;
        }
        for(int i=start; i<end; i++)
        {
            StringList* tmp = &box_strings[i];
            if(non_floating_behavior)
            {
                scale = real_scale;
                Render(&tmp->data, tmp->x, tmp->y);
            }
            else
            {
                float x = location_2d[0] - real_x;
                float y = location_2d[1] - real_y;
                if(scale > 0) Render(&tmp->data, tmp->x + x, tmp->y + y);
            }
        }
    }
}
